import { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { getVendorById, createVendor, updateVendor, normalizeVendorForSave } from '../../services/vendorService';
import { useNotification } from './NotificationSystem';
import { FiSave, FiX, FiUser, FiMail, FiPhone, FiMapPin, FiBriefcase, FiCreditCard, FiCheck, FiAlertCircle, FiHome, FiDollarSign, FiFileText, FiSettings, FiStar } from 'react-icons/fi';

export default function VendorForm() {
  const navigate = useNavigate();
  const { id } = useParams();
  const { showSuccess, showError } = useNotification();
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    address: '',
    city: '',
    state: '',
    zipCode: '',
    country: 'India',
    website: '',
    contactPerson: '',
    contactPhone: '',
    contactEmail: '',
    category: '',
    gstNumber: '',
    panNumber: '',
    bankDetails: {
      accountNumber: '',
      ifscCode: '',
      bankName: '',
      accountHolderName: ''
    },
    services: [],
    status: 'active',
    notes: '',
    establishedYear: '',
    employeeCount: '',
    annualRevenue: '',
    certifications: [],
    preferredPaymentTerms: '30',
    creditLimit: '',
    taxId: ''
  });

  const [errors, setErrors] = useState({});
  const [touched, setTouched] = useState({});

  useEffect(() => {
    if (id) {
      fetchVendor();
    }
  }, [id]);

  const fetchVendor = async () => {
    try {
      setLoading(true);
      const vendor = await getVendorById(id);
      if (!vendor) {
        showError('Vendor not found');
        navigate('/admin/vendors');
        return;
      }
      
      // Transform services and certifications from array to comma-separated string for input
      const transformedVendor = {
        ...vendor,
        services: Array.isArray(vendor.services) ? vendor.services.join(', ') : '',
        certifications: Array.isArray(vendor.certifications) ? vendor.certifications.join(', ') : '',
        bankDetails: {
          accountNumber: vendor.bankDetails?.accountNumber || '',
          ifscCode: vendor.bankDetails?.ifscCode || '',
          bankName: vendor.bankDetails?.bankName || '',
          accountHolderName: vendor.bankDetails?.accountHolderName || ''
        },
        preferredPaymentTerms: String(vendor.preferredPaymentTerms || '30'),
        employeeCount: vendor.employeeCount != null ? String(vendor.employeeCount) : '',
        annualRevenue: vendor.annualRevenue != null ? String(vendor.annualRevenue) : '',
        creditLimit: vendor.creditLimit != null ? String(vendor.creditLimit) : '',
        establishedYear: vendor.establishedYear != null ? String(vendor.establishedYear) : ''
      };

      setFormData(prev => ({
        ...prev,
        ...transformedVendor
      }));
    } catch (error) {
      console.error('Error fetching vendor:', error);
      showError('Failed to load vendor data');
    } finally {
      setLoading(false);
    }
  };

  const validateForm = () => {
    const newErrors = {};

    // Required field validations
    if (!formData.name.trim()) {
      newErrors.name = 'Vendor name is required';
    } else if (formData.name.length < 2) {
      newErrors.name = 'Vendor name must be at least 2 characters';
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email address';
    }

    if (!formData.phone.trim()) {
      newErrors.phone = 'Phone number is required';
    } else if (!/^[+]?[0-9]{10,15}$/.test(formData.phone.replace(/\s+/g, ''))) {
      newErrors.phone = 'Please enter a valid phone number (10-15 digits)';
    }

    if (!formData.address.trim()) {
      newErrors.address = 'Address is required';
    }

    if (!formData.city.trim()) {
      newErrors.city = 'City is required';
    }

    if (!formData.contactPerson.trim()) {
      newErrors.contactPerson = 'Contact person is required';
    }

    if (!formData.category.trim()) {
      newErrors.category = 'Category is required';
    }

    // GST Number validation (if provided)
    if (formData.gstNumber && !/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/.test(formData.gstNumber)) {
      newErrors.gstNumber = 'Please enter a valid GST number';
    }

    // PAN Number validation (if provided)
    if (formData.panNumber && !/^[A-Z]{5}[0-9]{4}[A-Z]{1}$/.test(formData.panNumber)) {
      newErrors.panNumber = 'Please enter a valid PAN number';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Mark all fields as touched to show errors
    const allFields = Object.keys(formData);
    const touchedFields = {};
    allFields.forEach(field => {
      touchedFields[field] = true;
    });
    setTouched(touchedFields);

    if (!validateForm()) {
      showError('Please fix the errors in the form');
      return;
    }

    try {
      setSaving(true);

      // Transform services and certifications back to array before saving
      const dataToSave = {
        ...formData,
        services: typeof formData.services === 'string' 
          ? formData.services.split(',').map(service => service.trim()).filter(service => service)
          : formData.services,
        certifications: typeof formData.certifications === 'string'
          ? formData.certifications.split(',').map(cert => cert.trim()).filter(cert => cert)
          : formData.certifications
      };

      const normalized = normalizeVendorForSave(dataToSave);
      
      if (id) {
        await updateVendor(id, normalized);
        showSuccess('Vendor updated successfully');
      } else {
        await createVendor(normalized);
        showSuccess('Vendor created successfully');
      }

      navigate('/admin/vendors');
    } catch (error) {
      console.error('Error saving vendor:', error);
      if (error?.message === 'DUPLICATE_VENDOR_EMAIL') {
        showError('A vendor with this email already exists');
        setErrors(prev => ({ ...prev, email: 'This email is already registered' }));
      } else if (error?.message === 'DUPLICATE_VENDOR_PHONE') {
        showError('A vendor with this phone already exists');
        setErrors(prev => ({ ...prev, phone: 'This phone number is already registered' }));
      } else {
        showError('Failed to save vendor');
      }
    } finally {
      setSaving(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));

    // Mark field as touched
    setTouched(prev => ({
      ...prev,
      [name]: true
    }));

    // Clear error when user starts typing
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const handleBankDetailsChange = (e) => {
    const { name, value } = e.target;
    const fieldName = name.split('.')[1];
    setFormData(prev => ({
      ...prev,
      bankDetails: {
        ...prev.bankDetails,
        [fieldName]: value
      }
    }));
  };

  const handleBlur = (e) => {
    const { name } = e.target;
    setTouched(prev => ({
      ...prev,
      [name]: true
    }));
  };

  const handleServicesChange = (e) => {
    const { value } = e.target;
    setFormData(prev => ({
      ...prev,
      services: value
    }));
  };

  const handleCertificationsChange = (e) => {
    const { value } = e.target;
    setFormData(prev => ({
      ...prev,
      certifications: value
    }));
  };

  const getInputClassName = (fieldName) => {
    const hasError = errors[fieldName] && touched[fieldName];
    return `w-full px-4 py-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all ${
      hasError ? 'border-red-500 bg-red-50' : 'border-gray-300 hover:border-gray-400'
    }`;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading vendor data...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 lg:p-6 bg-gray-50 min-h-screen">
      <div className="max-w-6xl mx-auto">
        {/* Enhanced Header Section */}
        <div className="mb-6">
          <div className="flex items-center space-x-3 mb-6">
            <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl flex items-center justify-center shadow-md">
              <FiBriefcase className="text-white" size={20} />
            </div>
            <div>
              <h1 className="text-2xl lg:text-3xl font-bold text-gray-900">
                {id ? 'Edit Vendor' : 'Add New Vendor'}
              </h1>
              <p className="text-gray-600 text-sm lg:text-base">
                {id ? 'Update vendor information and settings' : 'Create a new vendor profile'}
              </p>
            </div>
          </div>
          
          {/* Action Bar */}
          <div className="flex justify-end">
            <button
              onClick={() => navigate('/admin/vendors')}
              className="flex items-center space-x-2 px-4 py-2 bg-white border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors shadow-sm"
            >
              <FiX size={16} className="text-gray-600" />
              <span className="text-gray-700">Cancel</span>
            </button>
          </div>
        </div>
        
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
          <form onSubmit={handleSubmit} className="p-4 lg:p-6">
            {/* Enhanced Basic Information Section */}
            <div className="mb-8">
              <div className="flex items-center space-x-3 mb-6">
                <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-lg flex items-center justify-center shadow-sm">
                  <FiUser className="text-white" size={16} />
                </div>
                <h2 className="text-lg font-semibold text-gray-900">Basic Information</h2>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Vendor Name *
                  </label>
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleInputChange}
                    onBlur={handleBlur}
                    className={getInputClassName('name')}
                    placeholder="Enter vendor name"
                  />
                  {errors.name && touched.name && (
                    <div className="mt-1 flex items-center text-sm text-red-600">
                      <FiAlertCircle className="mr-1" size={14} />
                      {errors.name}
                    </div>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Category *
                  </label>
                  <select
                    name="category"
                    value={formData.category}
                    onChange={handleInputChange}
                    onBlur={handleBlur}
                    className={getInputClassName('category')}
                  >
                    <option value="">Select Category</option>
                    <option value="Manufacturing">Manufacturing</option>
                    <option value="Services">Services</option>
                    <option value="Technology">Technology</option>
                    <option value="Construction">Construction</option>
                    <option value="Logistics">Logistics</option>
                    <option value="Consulting">Consulting</option>
                    <option value="Other">Other</option>
                  </select>
                  {errors.category && touched.category && (
                    <div className="mt-1 flex items-center text-sm text-red-600">
                      <FiAlertCircle className="mr-1" size={14} />
                      {errors.category}
                    </div>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Email *
                  </label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    onBlur={handleBlur}
                    className={getInputClassName('email')}
                    placeholder="Enter email address"
                  />
                  {errors.email && touched.email && (
                    <div className="mt-1 flex items-center text-sm text-red-600">
                      <FiAlertCircle className="mr-1" size={14} />
                      {errors.email}
                    </div>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Phone *
                  </label>
                  <input
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    onBlur={handleBlur}
                    className={getInputClassName('phone')}
                    placeholder="Enter phone number"
                  />
                  {errors.phone && touched.phone && (
                    <div className="mt-1 flex items-center text-sm text-red-600">
                      <FiAlertCircle className="mr-1" size={14} />
                      {errors.phone}
                    </div>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Website
                  </label>
                  <input
                    type="url"
                    name="website"
                    value={formData.website}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="https://example.com"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Status
                  </label>
                  <select
                    name="status"
                    value={formData.status}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                  >
                    <option value="active">Active</option>
                    <option value="inactive">Inactive</option>
                    <option value="pending">Pending</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Enhanced Address Information */}
            <div className="border-t pt-8">
              <div className="flex items-center space-x-3 mb-6">
                <div className="w-8 h-8 bg-gradient-to-br from-green-500 to-emerald-600 rounded-lg flex items-center justify-center shadow-sm">
                  <FiHome className="text-white" size={16} />
                </div>
                <h3 className="text-lg font-semibold text-gray-900">Address Information</h3>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Address *
                  </label>
                  <input
                    type="text"
                    name="address"
                    value={formData.address}
                    onChange={handleInputChange}
                    onBlur={handleBlur}
                    className={getInputClassName('address')}
                    placeholder="Enter street address"
                  />
                  {errors.address && touched.address && (
                    <div className="mt-1 flex items-center text-sm text-red-600">
                      <FiAlertCircle className="mr-1" size={14} />
                      {errors.address}
                    </div>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    City *
                  </label>
                  <input
                    type="text"
                    name="city"
                    value={formData.city}
                    onChange={handleInputChange}
                    onBlur={handleBlur}
                    className={getInputClassName('city')}
                    placeholder="Enter city"
                  />
                  {errors.city && touched.city && (
                    <div className="mt-1 flex items-center text-sm text-red-600">
                      <FiAlertCircle className="mr-1" size={14} />
                      {errors.city}
                    </div>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    State
                  </label>
                  <input
                    type="text"
                    name="state"
                    value={formData.state}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter state"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    ZIP Code
                  </label>
                  <input
                    type="text"
                    name="zipCode"
                    value={formData.zipCode}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter ZIP code"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Country
                  </label>
                  <input
                    type="text"
                    name="country"
                    value={formData.country}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter country"
                  />
                </div>
              </div>
            </div>

            {/* Enhanced Contact Information */}
            <div className="border-t pt-8">
              <div className="flex items-center space-x-3 mb-6">
                <div className="w-8 h-8 bg-gradient-to-br from-purple-500 to-pink-600 rounded-lg flex items-center justify-center shadow-sm">
                  <FiPhone className="text-white" size={16} />
                </div>
                <h3 className="text-lg font-semibold text-gray-900">Primary Contact</h3>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Contact Person *
                  </label>
                  <input
                    type="text"
                    name="contactPerson"
                    value={formData.contactPerson}
                    onChange={handleInputChange}
                    onBlur={handleBlur}
                    className={getInputClassName('contactPerson')}
                    placeholder="Enter contact person"
                  />
                  {errors.contactPerson && touched.contactPerson && (
                    <div className="mt-1 flex items-center text-sm text-red-600">
                      <FiAlertCircle className="mr-1" size={14} />
                      {errors.contactPerson}
                    </div>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Contact Phone
                  </label>
                  <input
                    type="tel"
                    name="contactPhone"
                    value={formData.contactPhone}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter contact phone"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Contact Email
                  </label>
                  <input
                    type="email"
                    name="contactEmail"
                    value={formData.contactEmail}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter contact email"
                  />
                </div>
              </div>
            </div>

            {/* Enhanced Bank Details */}
            <div className="border-t pt-8">
              <div className="flex items-center space-x-3 mb-6">
                <div className="w-8 h-8 bg-gradient-to-br from-yellow-500 to-orange-600 rounded-lg flex items-center justify-center shadow-sm">
                  <FiCreditCard className="text-white" size={16} />
                </div>
                <h3 className="text-lg font-semibold text-gray-900">Bank Details</h3>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Account Number
                  </label>
                  <input
                    type="text"
                    name="bankDetails.accountNumber"
                    value={formData.bankDetails.accountNumber}
                    onChange={handleBankDetailsChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter account number"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    IFSC Code
                  </label>
                  <input
                    type="text"
                    name="bankDetails.ifscCode"
                    value={formData.bankDetails.ifscCode}
                    onChange={handleBankDetailsChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter IFSC code"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Bank Name
                  </label>
                  <input
                    type="text"
                    name="bankDetails.bankName"
                    value={formData.bankDetails.bankName}
                    onChange={handleBankDetailsChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter bank name"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Account Holder Name
                  </label>
                  <input
                    type="text"
                    name="bankDetails.accountHolderName"
                    value={formData.bankDetails.accountHolderName}
                    onChange={handleBankDetailsChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter account holder name"
                  />
                </div>
              </div>
            </div>

            {/* Enhanced GST and PAN Details */}
            <div className="border-t pt-8">
              <div className="flex items-center space-x-3 mb-6">
                <div className="w-8 h-8 bg-gradient-to-br from-red-500 to-pink-600 rounded-lg flex items-center justify-center shadow-sm">
                  <FiFileText className="text-white" size={16} />
                </div>
                <h3 className="text-lg font-semibold text-gray-900">GST and PAN Details</h3>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    GST Number
                  </label>
                  <input
                    type="text"
                    name="gstNumber"
                    value={formData.gstNumber}
                    onChange={handleInputChange}
                    onBlur={handleBlur}
                    className={getInputClassName('gstNumber')}
                    placeholder="Enter GST number"
                  />
                  {errors.gstNumber && touched.gstNumber && (
                    <div className="mt-1 flex items-center text-sm text-red-600">
                      <FiAlertCircle className="mr-1" size={14} />
                      {errors.gstNumber}
                    </div>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    PAN Number
                  </label>
                  <input
                    type="text"
                    name="panNumber"
                    value={formData.panNumber}
                    onChange={handleInputChange}
                    onBlur={handleBlur}
                    className={getInputClassName('panNumber')}
                    placeholder="Enter PAN number"
                  />
                  {errors.panNumber && touched.panNumber && (
                    <div className="mt-1 flex items-center text-sm text-red-600">
                      <FiAlertCircle className="mr-1" size={14} />
                      {errors.panNumber}
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* Enhanced Services */}
            <div className="border-t pt-8">
              <div className="flex items-center space-x-3 mb-6">
                <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center shadow-sm">
                  <FiSettings className="text-white" size={16} />
                </div>
                <h3 className="text-lg font-semibold text-gray-900">Services</h3>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Services
                  </label>
                  <input
                    type="text"
                    name="services"
                    value={formData.services}
                    onChange={handleServicesChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter services separated by commas (e.g., Web Development, Mobile Apps, Consulting)"
                  />
                  <p className="mt-1 text-sm text-gray-500">
                    Separate multiple services with commas
                  </p>
                </div>
              </div>
            </div>

            {/* Enhanced Certifications */}
            <div className="border-t pt-8">
              <div className="flex items-center space-x-3 mb-6">
                <div className="w-8 h-8 bg-gradient-to-br from-teal-500 to-cyan-600 rounded-lg flex items-center justify-center shadow-sm">
                  <FiStar className="text-white" size={16} />
                </div>
                <h3 className="text-lg font-semibold text-gray-900">Certifications</h3>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Certifications
                  </label>
                  <input
                    type="text"
                    name="certifications"
                    value={formData.certifications}
                    onChange={handleCertificationsChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter certifications separated by commas (e.g., ISO 9001, ISO 27001)"
                  />
                  <p className="mt-1 text-sm text-gray-500">
                    Separate multiple certifications with commas
                  </p>
                </div>
              </div>
            </div>

            {/* Enhanced Additional Information */}
            <div className="border-t pt-8">
              <div className="flex items-center space-x-3 mb-6">
                <div className="w-8 h-8 bg-gradient-to-br from-gray-500 to-gray-600 rounded-lg flex items-center justify-center shadow-sm">
                  <FiDollarSign className="text-white" size={16} />
                </div>
                <h3 className="text-lg font-semibold text-gray-900">Additional Information</h3>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Established Year
                  </label>
                  <input
                    type="number"
                    name="establishedYear"
                    value={formData.establishedYear}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter established year"
                    min="1900"
                    max={new Date().getFullYear()}
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Employee Count
                  </label>
                  <input
                    type="number"
                    name="employeeCount"
                    value={formData.employeeCount}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter employee count"
                    min="0"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Annual Revenue (₹)
                  </label>
                  <input
                    type="number"
                    name="annualRevenue"
                    value={formData.annualRevenue}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter annual revenue"
                    min="0"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Credit Limit (₹)
                  </label>
                  <input
                    type="number"
                    name="creditLimit"
                    value={formData.creditLimit}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter credit limit"
                    min="0"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Preferred Payment Terms
                  </label>
                  <select
                    name="preferredPaymentTerms"
                    value={formData.preferredPaymentTerms}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                  >
                    <option value="7">7 Days</option>
                    <option value="15">15 Days</option>
                    <option value="30">30 Days</option>
                    <option value="45">45 Days</option>
                    <option value="60">60 Days</option>
                    <option value="90">90 Days</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Enhanced Notes */}
            <div className="border-t pt-8">
              <div className="flex items-center space-x-3 mb-6">
                <div className="w-8 h-8 bg-gradient-to-br from-amber-500 to-yellow-600 rounded-lg flex items-center justify-center shadow-sm">
                  <FiFileText className="text-white" size={16} />
                </div>
                <h3 className="text-lg font-semibold text-gray-900">Notes</h3>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Notes
                  </label>
                  <textarea
                    name="notes"
                    value={formData.notes}
                    onChange={handleInputChange}
                    rows="4"
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all"
                    placeholder="Enter any additional notes or comments about the vendor"
                  />
                </div>
              </div>
            </div>

            {/* Enhanced Action Buttons */}
            <div className="border-t pt-8">
              <div className="flex flex-col sm:flex-row-reverse sm:justify-start justify-end items-stretch sm:items-center space-y-3 sm:space-y-0 sm:space-x-4 sm:space-x-reverse">
                <button
                  type="submit"
                  disabled={saving}
                  className="w-full sm:w-auto px-6 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 disabled:from-blue-400 disabled:to-indigo-400 rounded-lg text-white font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all flex items-center justify-center space-x-2 shadow-sm disabled:cursor-not-allowed"
                >
                  {saving ? (
                    <>
                      <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                      <span>Saving...</span>
                    </>
                  ) : (
                    <>
                      <FiSave size={16} />
                      <span>{id ? 'Update Vendor' : 'Add Vendor'}</span>
                    </>
                  )}
                </button>
                <button
                  type="button"
                  onClick={() => navigate('/admin/vendors')}
                  className="w-full sm:w-auto px-6 py-3 border border-gray-300 rounded-lg text-gray-700 font-medium hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all flex items-center justify-center space-x-2"
                >
                  <FiX size={16} />
                  <span>Cancel</span>
                </button>
              </div>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}